  UNIQUE(user_id, message_id)
);

-- table pending_move_notifications
CREATE TABLE pending_move_notifications (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL,
  account_id bigint NOT NULL,
  destination_mailbox_id bigint NOT NULL,
  raw_sha256 text COLLATE "C" NOT NULL,
  consumed_message_id bigint,
  created_at bigint NOT NULL,
  consumed_at bigint NOT NULL DEFAULT 0,
  expires_at bigint NOT NULL
);

-- table plugin_bimi_brand_icons
CREATE TABLE plugin_bimi_brand_icons (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL,
  domain text COLLATE "C" NOT NULL,
  logo_url text COLLATE "C" NOT NULL DEFAULT '',
  svg text COLLATE "C" NOT NULL DEFAULT '',
  status text COLLATE "C" NOT NULL DEFAULT '',
  error text COLLATE "C" NOT NULL DEFAULT '',
  fetched_at bigint NOT NULL DEFAULT 0,
  expires_at bigint NOT NULL DEFAULT 0,
  updated_at bigint NOT NULL DEFAULT 0,
  UNIQUE(user_id, domain)
);

-- table plugin_experimental_spam_backfills
CREATE TABLE plugin_experimental_spam_backfills (
  user_id bigint PRIMARY KEY,
  model_version text COLLATE "C" NOT NULL DEFAULT '',
  status text COLLATE "C" NOT NULL CHECK (status IN ('idle', 'running', 'complete', 'failed', 'cancelled')),
  requested bigint NOT NULL DEFAULT 0,
  processed bigint NOT NULL DEFAULT 0,
  failed bigint NOT NULL DEFAULT 0,
  last_message_id bigint NOT NULL DEFAULT 0,
  last_error text COLLATE "C" NOT NULL DEFAULT '',
  started_at bigint NOT NULL DEFAULT 0,
  updated_at bigint NOT NULL,
  completed_at bigint NOT NULL DEFAULT 0
);

-- table plugin_experimental_spam_bayes_documents
CREATE TABLE plugin_experimental_spam_bayes_documents (
  user_id bigint NOT NULL,
  message_fingerprint bytea NOT NULL CHECK (length(message_fingerprint) = 32),
  token_schema text COLLATE "C" NOT NULL,
  created_at bigint NOT NULL,
  updated_at bigint NOT NULL,
  PRIMARY KEY (user_id, message_fingerprint)
);

-- table plugin_experimental_spam_bayes_labels
CREATE TABLE plugin_experimental_spam_bayes_labels (
  user_id bigint NOT NULL,
  message_fingerprint bytea NOT NULL CHECK (length(message_fingerprint) = 32),
  source text COLLATE "C" NOT NULL CHECK (source IN ('explicit', 'automatic')),
  origin_key text COLLATE "C" NOT NULL,
  message_id bigint,
  label text COLLATE "C" NOT NULL CHECK (label IN ('spam', 'ham')),
  token_schema text COLLATE "C" NOT NULL,
  learned_at bigint NOT NULL,
  updated_at bigint NOT NULL,
  PRIMARY KEY (user_id, message_fingerprint, source, origin_key)
);

-- table plugin_experimental_spam_bayes_learn_tokens
CREATE TABLE plugin_experimental_spam_bayes_learn_tokens (
  user_id bigint NOT NULL,
  message_fingerprint bytea NOT NULL CHECK (length(message_fingerprint) = 32),
  token_hash bytea NOT NULL CHECK (length(token_hash) = 32),
  PRIMARY KEY (user_id, message_fingerprint, token_hash)
);

-- table plugin_experimental_spam_bayes_learns
CREATE TABLE plugin_experimental_spam_bayes_learns (
  user_id bigint NOT NULL,
  message_id bigint NOT NULL,
  message_fingerprint bytea NOT NULL CHECK (length(message_fingerprint) = 32),
  label text COLLATE "C" NOT NULL CHECK (label IN ('spam', 'ham')),
  source text COLLATE "C" NOT NULL DEFAULT 'explicit' CHECK (source IN ('explicit', 'automatic')),
  token_schema text COLLATE "C" NOT NULL,
  learned_at bigint NOT NULL,
  updated_at bigint NOT NULL,
  PRIMARY KEY (user_id, message_id)
);

-- table plugin_experimental_spam_bayes_state
CREATE TABLE plugin_experimental_spam_bayes_state (
  user_id bigint PRIMARY KEY,
  token_schema text COLLATE "C" NOT NULL,
  spam_messages bigint NOT NULL DEFAULT 0 CHECK (spam_messages >= 0),
  ham_messages bigint NOT NULL DEFAULT 0 CHECK (ham_messages >= 0),
  token_count bigint NOT NULL DEFAULT 0 CHECK (token_count >= 0),
  updated_at bigint NOT NULL
);

-- table plugin_experimental_spam_bayes_tokens
CREATE TABLE plugin_experimental_spam_bayes_tokens (
  user_id bigint NOT NULL,
  token_hash bytea NOT NULL CHECK (length(token_hash) = 32),
  spam_messages bigint NOT NULL DEFAULT 0 CHECK (spam_messages >= 0),
  ham_messages bigint NOT NULL DEFAULT 0 CHECK (ham_messages >= 0),
  last_seen bigint NOT NULL DEFAULT 0,
  PRIMARY KEY (user_id, token_hash)
);

-- table plugin_experimental_spam_bootstraps
CREATE TABLE plugin_experimental_spam_bootstraps (
  user_id bigint PRIMARY KEY,
  status text COLLATE "C" NOT NULL CHECK (status IN ('idle', 'running', 'complete', 'failed', 'cancelled')),
  cutoff_at bigint NOT NULL DEFAULT 0,
  candidate_spam bigint NOT NULL DEFAULT 0 CHECK (candidate_spam >= 0),
  candidate_ham bigint NOT NULL DEFAULT 0 CHECK (candidate_ham >= 0),
  examined bigint NOT NULL DEFAULT 0 CHECK (examined >= 0),
  accepted_spam bigint NOT NULL DEFAULT 0 CHECK (accepted_spam >= 0),
  accepted_ham bigint NOT NULL DEFAULT 0 CHECK (accepted_ham >= 0),
  rejected bigint NOT NULL DEFAULT 0 CHECK (rejected >= 0),
  current_mailbox text COLLATE "C" NOT NULL DEFAULT '',
  last_error text COLLATE "C" NOT NULL DEFAULT '',
  started_at bigint NOT NULL DEFAULT 0,
  updated_at bigint NOT NULL,
  completed_at bigint NOT NULL DEFAULT 0
);

-- table plugin_experimental_spam_classifications
CREATE TABLE plugin_experimental_spam_classifications (
  user_id bigint NOT NULL,
  message_id bigint NOT NULL,
  model_version text COLLATE "C" NOT NULL,
  base_probability double precision NOT NULL,
  labeled_neighbor_probability double precision NOT NULL DEFAULT 0.5,
  labeled_neighbor_count bigint NOT NULL DEFAULT 0,
  recent_read_support double precision NOT NULL DEFAULT 0,
  final_probability double precision NOT NULL,
  risk_band text COLLATE "C" NOT NULL CHECK (risk_band IN ('low', 'medium', 'high')),
  content_coverage text COLLATE "C" NOT NULL DEFAULT 'metadata',
  explanation_json text COLLATE "C" NOT NULL DEFAULT '{}',
  classified_at bigint NOT NULL,
  updated_at bigint NOT NULL,
  PRIMARY KEY (user_id, message_id)
);

-- table plugin_experimental_spam_feedback
CREATE TABLE plugin_experimental_spam_feedback (
  user_id bigint NOT NULL,
  message_id bigint NOT NULL,
  label text COLLATE "C" NOT NULL CHECK (label IN ('spam', 'ham')),
  created_at bigint NOT NULL,
  updated_at bigint NOT NULL,
  PRIMARY KEY (user_id, message_id)
);

-- table plugin_experimental_spam_pending_move_labels
CREATE TABLE plugin_experimental_spam_pending_move_labels (
  user_id bigint NOT NULL,
  account_id bigint NOT NULL,
  identity_key text COLLATE "C" NOT NULL,
  label text COLLATE "C" NOT NULL CHECK (label IN ('spam', 'ham')),
  source_mailbox_id bigint NOT NULL,
  destination_mailbox_id bigint NOT NULL,
  created_at bigint NOT NULL,
  expires_at bigint NOT NULL,
  PRIMARY KEY (user_id, account_id, identity_key)
);

-- table plugin_gravatar_cache
CREATE TABLE plugin_gravatar_cache (
