  PRIMARY KEY(rule_id, account_id)
);

-- table plugin_mail_filter_rules
CREATE TABLE plugin_mail_filter_rules (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL,
