);

-- table plugin_remote_imap_sync_messages
CREATE TABLE plugin_remote_imap_sync_messages (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL,
  routine_id bigint NOT NULL,
  source_uidvalidity bigint NOT NULL,
  source_uid bigint NOT NULL,
  source_fingerprint text COLLATE "C" NOT NULL,
  marker text COLLATE "C" NOT NULL,
  destination_uid bigint NOT NULL DEFAULT 0,
  status text COLLATE "C" NOT NULL DEFAULT 'transferred',
