CREATE TABLE plugin_remote_imap_sync_provenance (
  user_id bigint NOT NULL,
  destination_account_id bigint NOT NULL,
  destination_mailbox_id bigint NOT NULL,
  destination_uidvalidity bigint NOT NULL CHECK (destination_uidvalidity > 0),
  destination_uid bigint NOT NULL CHECK (destination_uid > 0),
  destination_sha256 text COLLATE "C" NOT NULL CHECK ( length(destination_sha256) = 64 AND destination_sha256 ~ '^[0-9a-f]*$' ),
  synced_at bigint NOT NULL CHECK (synced_at > 0),
  PRIMARY KEY (user_id, destination_account_id, destination_mailbox_id, destination_uidvalidity, destination_uid)
);

-- table plugin_remote_imap_sync_routines
CREATE TABLE plugin_remote_imap_sync_routines (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL,
  name text COLLATE "C" NOT NULL DEFAULT '',
  enabled bigint NOT NULL DEFAULT 1,
  source_provider text COLLATE "C" NOT NULL DEFAULT 'custom',
  source_host text COLLATE "C" NOT NULL,
  source_port bigint NOT NULL DEFAULT 993,
  source_username text COLLATE "C" NOT NULL,
  encrypted_source_password text COLLATE "C" NOT NULL,
  source_use_tls bigint NOT NULL DEFAULT 1,
  source_mailbox text COLLATE "C" NOT NULL DEFAULT 'INBOX',
  destination_account_id bigint NOT NULL,
  destination_mailbox_id bigint NOT NULL,
  after_date bigint NOT NULL DEFAULT 0,
  marker_secret text COLLATE "C" NOT NULL,
  source_uidvalidity bigint NOT NULL DEFAULT 0,
  last_source_uid bigint NOT NULL DEFAULT 0,
  state text COLLATE "C" NOT NULL DEFAULT 'paused',
  last_error text COLLATE "C" NOT NULL DEFAULT '',
  last_started_at bigint NOT NULL DEFAULT 0,
  last_completed_at bigint NOT NULL DEFAULT 0,
  last_activity_at bigint NOT NULL DEFAULT 0,
  next_retry_at bigint NOT NULL DEFAULT 0,
  transferred_total bigint NOT NULL DEFAULT 0,
  skipped_total bigint NOT NULL DEFAULT 0,
  created_at bigint NOT NULL,
  updated_at bigint NOT NULL,
  UNIQUE(id, user_id),
  UNIQUE(user_id, source_host, source_port, source_username, source_mailbox, destination_account_id, destination_mailbox_id)
);

-- table plugin_remote_imap_sync_runs
CREATE TABLE plugin_remote_imap_sync_runs (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL,
  routine_id bigint NOT NULL,
  trigger text COLLATE "C" NOT NULL DEFAULT 'scheduled',
  status text COLLATE "C" NOT NULL DEFAULT 'queued',
  scanned bigint NOT NULL DEFAULT 0,
  transferred bigint NOT NULL DEFAULT 0,
  skipped bigint NOT NULL DEFAULT 0,
  current_uid bigint NOT NULL DEFAULT 0,
  error text COLLATE "C" NOT NULL DEFAULT '',
  started_at bigint NOT NULL DEFAULT 0,
  completed_at bigint NOT NULL DEFAULT 0,
  created_at bigint NOT NULL
);

