);

-- table remote_image_cache
CREATE TABLE remote_image_cache (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL,
  url_hash text COLLATE "C" NOT NULL,
  url text COLLATE "C" NOT NULL,
  blob_id bigint NOT NULL DEFAULT 0,
  blob_path text COLLATE "C" NOT NULL DEFAULT '',
  content_type text COLLATE "C" NOT NULL DEFAULT '',
  size bigint NOT NULL DEFAULT 0,
  status text COLLATE "C" NOT NULL,
  error text COLLATE "C" NOT NULL DEFAULT '',
  fetched_at bigint NOT NULL DEFAULT 0,
  expires_at bigint NOT NULL DEFAULT 0,
  created_at bigint NOT NULL,
  updated_at bigint NOT NULL,
