  PRIMARY KEY(scope, version)
);

-- table sender_read_stats
CREATE TABLE sender_read_stats (
  user_id bigint NOT NULL,
  sender text COLLATE "C" NOT NULL,
  read_count bigint NOT NULL DEFAULT 0,
  total_count bigint NOT NULL DEFAULT 0,
  boost double precision NOT NULL DEFAULT 0,
  updated_at bigint NOT NULL,
  PRIMARY KEY(user_id, sender)
);

-- table sessions
CREATE TABLE sessions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL,
  token_hash text COLLATE "C" NOT NULL UNIQUE,
  expires_at bigint NOT NULL,
  created_at bigint NOT NULL,
  last_seen_at bigint NOT NULL
);

-- table smtp_accounts
CREATE TABLE smtp_accounts (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL,
  label text COLLATE "C" NOT NULL DEFAULT '',
  host text COLLATE "C" NOT NULL,
  port bigint NOT NULL DEFAULT 587,
  username text COLLATE "C" NOT NULL DEFAULT '',
  encrypted_password text COLLATE "C" NOT NULL DEFAULT '',
  use_tls bigint NOT NULL DEFAULT 1,
  created_at bigint NOT NULL,
  updated_at bigint NOT NULL,
  auth_type text COLLATE "C" NOT NULL DEFAULT 'password',
  google_connection_id bigint NOT NULL DEFAULT 0
);

-- table snooze_reminder_events
CREATE TABLE snooze_reminder_events (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL,
  message_id bigint NOT NULL,
  snooze_generation bigint NOT NULL,
  from_addr text COLLATE "C" NOT NULL DEFAULT '',
  subject text COLLATE "C" NOT NULL DEFAULT '',
  due_at bigint NOT NULL,
  created_at bigint NOT NULL,
  UNIQUE(user_id, message_id, snooze_generation)
);

-- table swipe_archive_mailboxes
CREATE TABLE swipe_archive_mailboxes (
  user_id bigint NOT NULL,
  account_id bigint NOT NULL,
  mailbox_id bigint NOT NULL,
  created_at bigint NOT NULL,
  updated_at bigint NOT NULL,
  PRIMARY KEY(user_id, account_id),
  UNIQUE(user_id, mailbox_id)
);

-- table swipe_preferences
CREATE TABLE swipe_preferences (
  user_id bigint PRIMARY KEY,
  left_action text COLLATE "C" NOT NULL DEFAULT 'snooze' CHECK(left_action IN ('trash', 'archive', 'snooze', 'mark_read', 'mark_unread')),
  left_snooze_preset text COLLATE "C" NOT NULL DEFAULT 'tomorrow' CHECK(left_snooze_preset IN ('later_today', 'tomorrow', 'next_week')),
  right_action text COLLATE "C" NOT NULL DEFAULT 'mark_read' CHECK(right_action IN ('trash', 'archive', 'snooze', 'mark_read', 'mark_unread')),
  right_snooze_preset text COLLATE "C" NOT NULL DEFAULT 'tomorrow' CHECK(right_snooze_preset IN ('later_today', 'tomorrow', 'next_week')),
  created_at bigint NOT NULL,
  updated_at bigint NOT NULL
);

-- table sync_runs
CREATE TABLE sync_runs (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL,
  account_id bigint NOT NULL,
  status text COLLATE "C" NOT NULL,
  started_at bigint NOT NULL,
  finished_at bigint NOT NULL DEFAULT 0,
  updated_at bigint NOT NULL DEFAULT 0,
  messages_seen bigint NOT NULL DEFAULT 0,
  messages_stored bigint NOT NULL DEFAULT 0,
  messages_skipped bigint NOT NULL DEFAULT 0,
  new_messages bigint NOT NULL DEFAULT 0,
  latest_new_from text COLLATE "C" NOT NULL DEFAULT '',
  latest_new_subject text COLLATE "C" NOT NULL DEFAULT '',
  messages_total bigint NOT NULL DEFAULT 0,
  mailboxes_done bigint NOT NULL DEFAULT 0,
  mailboxes_total bigint NOT NULL DEFAULT 0,
  current_mailbox text COLLATE "C" NOT NULL DEFAULT '',
  current_uid bigint NOT NULL DEFAULT 0,
  error text COLLATE "C" NOT NULL DEFAULT '',
  latest_new_message_id bigint NOT NULL DEFAULT 0
);

-- table system_settings
CREATE TABLE system_settings (
  key text COLLATE "C" PRIMARY KEY,
  value text COLLATE "C" NOT NULL DEFAULT '',
  created_at bigint NOT NULL,
  updated_at bigint NOT NULL
);

-- table users
CREATE TABLE users (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  email text COLLATE "C" NOT NULL UNIQUE,
  name text COLLATE "C" NOT NULL,
  password_hash text COLLATE "C" NOT NULL,
  is_admin bigint NOT NULL DEFAULT 0,
  date_locale text COLLATE "C" NOT NULL DEFAULT '',
  date_format text COLLATE "C" NOT NULL DEFAULT 'mdy',
  theme text COLLATE "C" NOT NULL DEFAULT 'classic',
  created_at bigint NOT NULL,
  updated_at bigint NOT NULL,
  search_preset text COLLATE "C" NOT NULL DEFAULT 'balanced',
  search_recency_bias text COLLATE "C" NOT NULL DEFAULT 'normal',
  search_fuzzy text COLLATE "C" NOT NULL DEFAULT 'balanced',
  search_sender_boost bigint NOT NULL DEFAULT 1,
  search_attachment_weight text COLLATE "C" NOT NULL DEFAULT 'normal',
  search_compact_splitting bigint NOT NULL DEFAULT 1,
  search_sender_history text COLLATE "C" NOT NULL DEFAULT 'normal',
  search_contact_boost text COLLATE "C" NOT NULL DEFAULT 'normal',
  backup_email text COLLATE "C" NOT NULL DEFAULT ''
);

-- table web_push_subscriptions
CREATE TABLE web_push_subscriptions (
  id bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  user_id bigint NOT NULL,
  endpoint text COLLATE "C" NOT NULL,
  p256dh text COLLATE "C" NOT NULL,
  auth text COLLATE "C" NOT NULL,
  user_agent text COLLATE "C" NOT NULL DEFAULT '',
  created_at bigint NOT NULL,
  updated_at bigint NOT NULL,
  last_seen_at bigint NOT NULL,
  last_new_mail_event_id bigint NOT NULL DEFAULT 0,
  last_snooze_reminder_event_id bigint NOT NULL DEFAULT 0,
  UNIQUE(user_id, endpoint)
);

