CREATE INDEX idx_contact_emails_user_address ON contact_emails (user_id, normalized_email);

-- index idx_contact_emails_user_contact
CREATE INDEX idx_contact_emails_user_contact ON contact_emails (user_id, contact_id);

-- index idx_contact_icons_user_contact
CREATE INDEX idx_contact_icons_user_contact ON contact_icons (user_id, contact_id);

-- index idx_contact_pgp_public_keys_user_contact
CREATE INDEX idx_contact_pgp_public_keys_user_contact ON contact_pgp_public_keys (user_id, contact_id);

-- index idx_contact_pgp_public_keys_user_email
CREATE INDEX idx_contact_pgp_public_keys_user_email ON contact_pgp_public_keys (user_id, normalized_email, is_preferred DESC);

-- index idx_contact_phones_user_contact
CREATE INDEX idx_contact_phones_user_contact ON contact_phones (user_id, contact_id);

-- index idx_contact_urls_user_contact
CREATE INDEX idx_contact_urls_user_contact ON contact_urls (user_id, contact_id);

