CREATE INDEX idx_expunged_message_fingerprints_canonical ON expunged_message_fingerprints (user_id, account_id, canonical_sha256, expires_at, id) WHERE consumed_at = 0 AND canonical_sha256 <> '';

-- index idx_expunged_message_fingerprints_expiry
CREATE INDEX idx_expunged_message_fingerprints_expiry ON expunged_message_fingerprints (user_id, expires_at);

-- index idx_expunged_message_fingerprints_message_id
CREATE INDEX idx_expunged_message_fingerprints_message_id ON expunged_message_fingerprints (user_id, account_id, message_id_hash, internal_date_unix, message_size, expires_at, id) WHERE consumed_at = 0 AND message_id_hash <> '';

-- index idx_expunged_message_fingerprints_raw
